-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "4d320052-aa80-4a44-8378-df8a4c22bcd3", "shop": "Parkermo", "listing_id": "1702252202", "source_url": "https://www.etsy.com/listing/1702252202/checkered-cotton-linen-curtain-milk-tea", "category": "Linen Curtains", "image_url": null, "destination_url": "https://www.etsy.com/listing/1702252202/checkered-cotton-linen-curtain-milk-tea", "title": "Natural Linen Blend Tab Top Curtain, Grid Check Sheer Panel, Farmhouse Window Curtain", "body": "Natural Linen Blend Tab Top Curtain, Grid Check Sheer Panel, Farmhouse Window Curtain Style: checkered, farmhouse, natural. Materials: cotton, linen. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/41687571/r/il/a29feb/8295040734/il_794xN.8295040734_6vwt.jpg", "new_title": "Grid-Check Sheer Curtain", "new_body": "A natural-toned grid pattern brings a relaxed detail to a window. This sheer curtain from Parkermo comes with size, heading and panel-quantity options. Curtain rod is not included. See the original listing for details.", "facebook_draft": "A light window refresh with a subtle grid pattern. Explore Parkermo\u2019s available curtain sizes and heading options; rod not included. https://www.etsy.com/listing/1702252202/checkered-cotton-linen-curtain-milk-tea", "board_id": "801218658646993070", "checked_at": "2026-10-19T02:11:47.649028+00:00", "visual_verified": true, "available": true}, {"queue_id": "77663707-bb0c-4a71-8176-e8f23bde28ba", "shop": "ShirieHomeShow", "listing_id": "4299980520", "source_url": "https://www.etsy.com/listing/4299980520/lemon-embroidered-sheer-curtain", "category": "Sheer Curtains", "image_url": null, "destination_url": "https://www.etsy.com/listing/4299980520/lemon-embroidered-sheer-curtain", "title": "Lemon Embroidered Sheer Curtain", "body": "Lemon Embroidered Sheer Curtain Style: embroidered, botanical. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/46873252/r/il/3f619a/6882779077/il_794xN.6882779077_60e4.jpg", "new_title": "Lemon Embroidered Sheer Curtain", "new_body": "Yellow lemons and green leaves decorate this sheer polyester curtain from ShirieHomeShow. Explore the original listing for panel sizes, quantity and heading options. Fabric samples are listed separately from full panels.", "facebook_draft": "A cheerful lemon-and-leaf detail for a kitchen window. ShirieHomeShow offers this sheer curtain in several sizes and headings. Choose a full panel option rather than a fabric sample. https://www.etsy.com/listing/4299980520/lemon-embroidered-sheer-curtain", "board_id": "801218658646993070", "checked_at": "2026-10-19T02:11:47.649385+00:00", "visual_verified": true, "available": true}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text,facebook_draft text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id)
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 2 then raise exception 'Expected 2 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','daily-20261019-b4')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body=x.facebook_draft
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;


commit;
